import AppHead from '../common/AppHeader.vue';
import AppBody from '../common/AppPageBody.vue'
import AppFoot from '../common/AppFoot.vue'

export default {
    name: "order",
    components: {
        AppHead,
        AppBody,
        AppFoot
    },
    data() {
        return {
            addressDialogVisible:false,
            addressData: [],
            orderStatus: ['待付款', '待发货', '待收货', '已完成', '已取消'],
            orderInfo: {
                createTime: "",
                id: 0,
                idleId: 0,
                idleItem: {
                    id: '',
                    idleName: '',
                    idleDetails: '',
                    pictureList: [],
                    idlePrice: 0,
                    idlePlace: '',
                    idleLabel: '',
                    idleStatus: -1,
                    userId: '',
                },
                orderNumber: "",
                orderPrice: 0,
                orderStatus: 0,
                paymentStatus: 0,
                paymentTime: "",
                paymentWay: "支付宝",
                userId: 0
            },
            addressInfo: {
                id:'',
                update:false,
                consigneeName: '',
                consigneePhone: '',
                detailAddress: ''
            },
            userId:''
        };
    },
    created() {
        this.userId = this.getCookie('shUserId');
        console.log('userId', this.userId);
        let orderId = this.$route.query.id;
        console.log('orderId', orderId);

        this.$api.getOrder({
            id: orderId
        }).then(res => {
            console.log('getOrder response', res);
            if (res.status_code === 1) {
                // 保存当前硬编码的 paymentWay
                const originalPaymentWay = this.orderInfo.paymentWay; // "支付宝"

                // 原始逻辑：处理 idleItem 图片
                if (res.data.idleItem) {
                    let imgList = JSON.parse(res.data.idleItem.pictureList);
                    if (imgList.length > 0) {
                        res.data.idleItem.imgUrl = imgList[0];
                    } else {
                        res.data.idleItem.imgUrl = '';
                    }
                } else {
                    res.data.idleItem = {
                        idleName: '',
                        imgUrl: ''
                    }
                }

                // 覆盖其他字段，但保留 paymentWay
                this.orderInfo = {
                    ...res.data,                // 后端数据
                    paymentWay: originalPaymentWay // 强制保留硬编码值
                };

                console.log('orderInfo.paymentWay:', this.orderInfo.paymentWay); // 确保是"支付宝"

                // 原始地址逻辑不变
                this.$api.getOrderAddress({
                    orderId: this.orderInfo.id
                }).then(addressRes => {
                    if (addressRes.data) {
                        this.addressInfo = addressRes.data;
                        this.addressInfo.update = true;
                    } else {
                        this.getAddressData();
                    }
                });
            }
        })
    },
    methods: {
        getCookie(cname){
            var name = cname + "=";
            var ca = document.cookie.split(';');
            for(var i=0; i<ca.length; i++)
            {
                var c = ca[i].trim();
                if (c.indexOf(name)===0) return c.substring(name.length,c.length);
            }
            return "0";
        },
        toDetails(id) {
            this.$router.replace({path: 'details', query: {id: id}});
        },
        selectAddressDialog(){
            if(this.orderInfo.userId==this.userId&&this.orderInfo.orderStatus===0){
                this.addressDialogVisible=true;
                if(this.addressData.length===0){
                    this.getAddressData();
                }
            }
        },
        getAddressData(){
            this.$api.getAddress().then(res => {
                if (res.status_code === 1) {
                    let data = res.data;
                    for (let i = 0; i < data.length; i++) {
                        data[i].detailAddressText = data[i].provinceName + data[i].cityName + data[i].regionName + data[i].detailAddress;
                    }
                    console.log(data);
                    this.addressData = data;
                    if(!this.addressInfo.update){
                        for(let i=0;i<data.length;i++){
                            if(data[i].defaultFlag){
                                this.selectAddress(i,data[i]);
                            }
                        }
                    }
                }
            })
        },
        selectAddress(i,item){
            this.addressDialogVisible=false;
            console.log(item,this.addressInfo);
            this.addressInfo.consigneeName=item.consigneeName;
            this.addressInfo.consigneePhone=item.consigneePhone;
            this.addressInfo.detailAddress=item.detailAddressText;
            if(this.addressInfo.update){
                this.$api.updateOrderAddress({
                    id:this.addressInfo.id,
                    consigneeName:item.consigneeName,
                    consigneePhone:item.consigneePhone,
                    detailAddress:item.detailAddressText
                })
            }else{
                this.$api.addOrderAddress({
                    orderId:this.orderInfo.id,
                    consigneeName:item.consigneeName,
                    consigneePhone:item.consigneePhone,
                    detailAddress:item.detailAddressText
                }).then(res=>{
                    if(res.status_code===1){
                        this.addressInfo.update=true;
                        this.addressInfo.id=res.data.id;
                    }else {
                        this.$message.error(res.msg)
                    }
                })
            }

        },
        changeOrderStatus(orderStatus, orderInfo) {
            if (orderStatus === 1) {
                console.log('zhifu');
                if (!this.addressInfo.detailAddress) {
                    this.$message.error('请选择地址！');
                } else {
                    this.$confirm('模拟支付宝支付，是否确认支付', '支付订单', {
                        confirmButtonText: '支付',
                        cancelButtonText: '取消',
                        type: 'warning'
                    }).then(() => {
                        this.$api.updateOrder({
                            id: orderInfo.id,
                            orderStatus: orderStatus,
                            paymentStatus: 1,
                            paymentWay: '支付宝',
                        }).then(res => {
                            if (res.status_code === 1) {
                                // 支付成功，下架商品
                                this.$api.updateIdleItem({
                                    id: orderInfo.idleId,
                                    idleStatus: 2 // 已下架
                                }).then(() => {
                                    this.$message({
                                        message: '支付成功！',
                                        type: 'success'
                                    });
                                    this.orderInfo.orderStatus = orderStatus;
                                    this.orderInfo.paymentStatus = 1;
                                    this.orderInfo.paymentWay = '支付宝';
                                    this.orderInfo.paymentTime = res.data.paymentTime;
                                });
                            }
                        });
                    }).catch(() => {});
                }
            } else {
                this.$api.updateOrder({
                    id: orderInfo.id,
                    orderStatus: orderStatus,
                }).then(res => {
                    if (res.status_code === 1) {
                        this.$message({
                            message: '操作成功！',
                            type: 'success'
                        });
                        this.orderInfo.orderStatus = orderStatus;
                    }
                });
            }
        },
    }

}
